+        if (/^\d+$/.test(pathParts[i])) {
+            buildNumber = parseInt(pathParts[i], 10);
+            break;
+        }
+        jobPathParts.push(pathParts[i]);
+    }
+    if (!buildNumber || jobPathParts.length === 0) return null;
+    return { jobPath: jobPathParts.join('/'), buildNumber: buildNumber };
